const WellnessMetrics = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [metricsData, setMetricsData] = useState(null);

  const fetchMetricsData = async () => {
    try {
      setLoading(true);
      setError(null);
      const result = await getWellnessAnalytics({ teacher_id, timeframe });
      setMetricsData(result.data);
    } catch (err) {
      setError(err.message || 'Failed to load metrics data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <LoadingSpinner />;
  if (error) return <ErrorMessage error={error} onRetry={fetchMetricsData} />;
  if (!metricsData) return <NoDataMessage />;

  return <MetricsDisplay data={metricsData} />;
};

