// 3. Batch updates for performance
const updateWellnessData = (updates) => {
  const batch = db.batch();
  updates.forEach(update => {
    const ref = db.doc(update.path);
    batch.set(ref, update.data, { merge: true });
  });
  return batch.commit();
};
